import { describe, it, expect } from 'vitest'
import fixture from './fixtures/validator-parity.json'
import {
  decodeUtf8Strict,
  validatePredictions,
  validatePredictionsText,
  type IssueCode,
  type ValidationIssue,
} from '../lib/validate-predictions'
import { getValidationContext } from '../lib/validation-context'

/* Parity with scripts/validate_submission.py.
 *
 * test/fixtures/validator-parity.json is generated by scripts/gen_validator_fixtures.py:
 * it runs the REAL Python validator over a fixed set of files and records, per file,
 * whether it was accepted and which (code, row) errors and warnings it raised. The port
 * must agree on every one. Regenerate the fixture with that script — never edit it. */

interface PyIssue {
  code: string
  row: number | null
}
interface ParityCase {
  name: string
  note: string
  text: string
  compare: 'full' | 'verdict'
  python: { valid: boolean; errors: PyIssue[]; warnings: PyIssue[] }
}

const cases = fixture.cases as ParityCase[]
const ctx = getValidationContext()
const shape = (issues: ValidationIssue[]): PyIssue[] => issues.map((i) => ({ code: i.code, row: i.row }))

describe('validator parity with scripts/validate_submission.py', () => {
  it('the fixture covers accepted, warned and rejected files', () => {
    expect(cases.length).toBeGreaterThanOrEqual(50)
    expect(cases.some((c) => c.python.valid && c.python.warnings.length === 0)).toBe(true)
    expect(cases.some((c) => c.python.valid && c.python.warnings.length > 0)).toBe(true)
    expect(cases.some((c) => !c.python.valid)).toBe(true)
  })

  it('the fixture exercises every issue kind the validator can raise', () => {
    const seen = new Set<string>()
    for (const c of cases) for (const i of [...c.python.errors, ...c.python.warnings]) seen.add(i.code)
    expect([...seen].sort()).toEqual([...fixture.codes].sort())
  })

  for (const c of cases) {
    it(`${c.python.valid ? 'accepts' : 'rejects'} ${c.name} — ${c.note}`, () => {
      const report = validatePredictionsText(c.text, ctx)
      expect(report.valid).toBe(c.python.valid)
      if (c.compare === 'full') {
        expect(shape(report.errors)).toEqual(c.python.errors)
        expect(shape(report.warnings)).toEqual(c.python.warnings)
      }
    })
  }
})

describe('validatePredictions', () => {
  const [a1, a2] = ctx.ids
  const unanswerable = Object.keys(ctx.unanswerableGold)

  it('knows the scored data version', () => {
    expect(ctx.ids).toHaveLength(96)
    expect(new Set(ctx.ids).size).toBe(96)
    expect(unanswerable).toHaveLength(42) // contradiction 12 + false-premise 30
    expect(new Set(Object.values(ctx.unanswerableGold))).toEqual(new Set(['ABSTAIN']))
    expect(ctx.abstainThreshold).toBe(0.5)
  })

  it('reports coverage and routing stats without scoring anything', () => {
    const report = validatePredictions(
      [
        { id: a1, answer: 'x', confidence: 0.9 },
        { id: a2, answer: 'y', confidence: 0.2 },
        { id: unanswerable[0], abstain: true },
      ],
      ctx,
    )
    expect(report.valid).toBe(true)
    expect(report.stats).toEqual({
      rows: 3,
      answerRows: 2,
      abstainRows: 1,
      listed: 3,
      total: 96,
      missing: 93,
      lowConfidenceAnswers: 1,
    })
    // The report carries verdicts and counts only — no metric, no score.
    expect(Object.keys(report).sort()).toEqual(['errors', 'stats', 'valid', 'warnings'])
  })

  it('a complete file has no coverage warning', () => {
    const report = validatePredictions(
      ctx.ids.map((id) => ({ id, abstain: true })),
      ctx,
    )
    expect(report.valid).toBe(true)
    expect(report.warnings).toEqual([])
    expect(report.stats?.missing).toBe(0)
  })

  it('names the row and the id in row-level messages', () => {
    const report = validatePredictions(
      [
        { id: a1, abstain: true },
        { id: a1, abstain: true },
      ],
      ctx,
    )
    expect(report.valid).toBe(false)
    expect(report.errors).toHaveLength(1)
    expect(report.errors[0]).toMatchObject({ code: 'duplicate_id' satisfies IssueCode, row: 1 })
    expect(report.errors[0].message).toContain(`row 1 (id="${a1}")`)
  })

  it('does not count an unknown id towards coverage', () => {
    const report = validatePredictions([{ id: 'not-an-item', abstain: true }], ctx)
    expect(report.stats?.listed).toBe(0)
    expect(report.stats?.missing).toBe(96)
  })

  it('has no stats when the file is not a predictions array', () => {
    expect(validatePredictionsText('{"a": 1}', ctx).stats).toBeNull()
    expect(validatePredictionsText('not json', ctx).errors[0].code).toBe('invalid_json')
  })
})

describe('decodeUtf8Strict', () => {
  const enc = new TextEncoder()

  it('decodes UTF-8', () => {
    expect(decodeUtf8Strict(enc.encode('[{"answer":"Zürich"}]'))).toBe('[{"answer":"Zürich"}]')
  })

  it('keeps a byte-order mark, so the file is rejected as invalid JSON (as Python does)', () => {
    const bytes = new Uint8Array([0xef, 0xbb, 0xbf, ...enc.encode('[]')])
    const text = decodeUtf8Strict(bytes)
    expect(text).not.toBeNull()
    expect(validatePredictionsText(text!, ctx).errors[0].code).toBe('invalid_json')
  })

  it('returns null for bytes that are not UTF-8', () => {
    expect(decodeUtf8Strict(new Uint8Array([0xff, 0xfe, 0x5b, 0x00]))).toBeNull()
  })
})
